mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("abba; red blue blue red","true"),
        ("abba; red blue blue green","false"),
        ("ab; red red","false"),
        ("aaa; red red red","true"),
        ("abc; one two three","true"),
        ("  \nabba; red blue blue red\n  ","true"),
        ("\nabc; one two three\n","true")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS bidirectional-map");
}
